function area(a){let v=0;for(let i=0;i<a.length;i++)v+=cross(a[i],a[(i+1)%a.length]);return v/2;}function polyArea(o){return Math.max(0,Math.abs(area(o.pts))-(o.holes||[]).reduce((s,h)=>s+Math.abs(area(h)),0));}function length(a){return a.slice(1).reduce((s,b,i)=>s+dist(a[i],b),0);}function centroid(a){return a.reduce((s,b)=>add(s,mul(b,1/a.length)),[0,0]);}function bbox(a){return a.reduce((b,v)=>[Math.min(b[0],v[0]),Math.min(b[1],v[1]),Math.max(b[2],v[0]),Math.max(b[3],v[1])],[Infinity,Infinity,-Infinity,-Infinity]);}function inBox(a,b){return a[0]>=b[0]&&a[0]<=b[2]&&a[1]>=b[1]&&a[1]<=b[3];}
function nearest(a,b,c){let v=sub(c,b),d=dot(v,v);return lerp(b,c,d?clamp(dot(sub(a,b),v)/d,0,1):0);}function inside(a,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let b=poly[i],c=poly[j];if((b[1]>a[1])!==(c[1]>a[1])&&a[0]<(c[0]-b[0])*(a[1]-b[1])/(c[1]-b[1])+b[0])yes=!yes;}return yes;}function insideObj(a,o){return inside(a,o.pts)&&!(o.holes||[]).some(h=>inside(a,h));}
function segCross(a,b,c,d){let ab=sub(b,a),cd=sub(d,c),z=cross(ab,cd);if(Math.abs(z)<1e-8)return false;let ac=sub(c,a),u=cross(ac,cd)/z,v=cross(ac,ab)/z;return u>1e-7&&u<1-1e-7&&v>1e-7&&v<1-1e-7;}function simple(a){if(a.length<3||Math.abs(area(a))<.1)return false;for(let i=0;i<a.length;i++){if(dist(a[i],a[(i+1)%a.length])<.001)return false;for(let j=i+2;j<a.length;j++){if(i===0&&j===a.length-1)continue;if(segCross(a[i],a[(i+1)%a.length],a[j],a[(j+1)%a.length]))return false;}}return true;}
