function roadPts(r){return r.smooth?rounded(r.pts):r.pts;}function offset(pts,d){const ns=pts.slice(1).map((b,i)=>perp(norm(sub(b,pts[i]))));return pts.map((a,i)=>{if(i===0)return add(a,mul(ns[0],d));if(i===pts.length-1)return add(a,mul(ns.at(-1),d));let v=add(ns[i-1],ns[i]),den=dot(v,ns[i]);return add(a,mul(Math.abs(den)>.1?v:ns[i],clamp(Math.abs(den)>.1?d/den:d,-Math.abs(d)*4,Math.abs(d)*4)));});}
