function allObjects(){return [...(p.boundary?[['boundary',p.boundary]]:[]),...p.roads.map(o=>['road',o]),...p.rounds.map(o=>['round',o]),...p.blocks.map(o=>['block',o]),...p.lots.map(o=>['lot',o]),...p.zones.map(o=>['zone',o])];}function find(id){return allObjects().find(x=>x[1].id===id)||null;}function selected(){return selection?find(selection):null;}function layerOf(t){return t==='round'?'road':t;}
function snapshot(){return JSON.stringify(p);}function commit(before,geometry=false){if(before===snapshot())return;invalidateParcel();onBlockCommit(before);undoStack.push(before);if(undoStack.length>35)undoStack.shift();redoStack=[];dirtySave=true;renderAll();scheduleMetrics();autoSave();}function replaceState(s){invalidateParcel();p=JSON.parse(s);normalizePrecision(p);normalizeParcel(p);p.params={...defaults,...p.params};selection=null;draft=[];refRoad=null;renderAll();scheduleMetrics();autoSave();}function undo(){if(!undoStack.length)return;redoStack.push(snapshot());replaceState(undoStack.pop());}function redo(){if(!redoStack.length)return;undoStack.push(snapshot());replaceState(redoStack.pop());}
