function renderTools(){const groups=[['select','pan'],['boundary','road','curve','parallel','round'],['block','lot','zone','parcelArea'],['measure','angle','guide','guideOffset']];$('tools').innerHTML=groups.map((g,i)=>(i?'<div style="height:8px"></div>':'')+g.map(k=>{let [name,,icon,key]=types[k];return `<button class="tool ${mode===k?'on':''}" data-tool="${k}"><span class="ico">${icon}</span><span class="label">${name}</span><kbd>${key}</kbd></button>`;}).join('')).join('');$('modeTitle').textContent=types[mode][0];$('modeHelp').textContent=types[mode][1];$('finish').disabled=!['boundary','road','curve','block','lot','zone','round','parcelArea'].includes(mode);$('del').disabled=!selection||!!(selected()?.[0]==='block'&&selected()?.[1].auto);$('undo').disabled=!undoStack.length;$('redo').disabled=!redoStack.length;svg.style.cursor=mode==='select'?'default':mode==='pan'?'grab':'crosshair';$('empty').classList.toggle('hidden',!!p.boundary||p.roads.length>0||mode!=='select');}
function field(key,label,val,min,max,step=1,extra=''){return `<div class="field"><label>${label}</label><input data-param="${key}" type="number" value="${esc(val)}" min="${min}" max="${max}" step="${step}" ${extra}></div>`;}function opts(obj,val){return Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===val?'selected':''}>${esc(Array.isArray(v)?v[0]:v)}</option>`).join('');}
function renderParams(){let a=p.params;let h='';if(['road','curve','parallel','select','pan'].includes(mode)){h+=`<div class="field"><label>Hierarquia viária</label><select data-param="roadClass">${opts({Local:'Local',Coletora:'Coletora',Arterial:'Arterial',Pedonal:'Pedonal'},a.roadClass)}</select></div>`+field('width','Largura total da via (m)',a.width,1,100,.5);if(mode==='parallel')h+=field('gap','Distância livre entre divisas (m)',a.gap,0,1000,.5)+field('copies','Quantidade de cópias',a.copies,1,12);}else if(mode==='round'){h+=field('roundRadius','Raio externo sugerido (m)',a.roundRadius,3,150,.5)+field('roundWidth','Largura do anel (m)',a.roundWidth,1,100,.5)+'<p class="hint">O segundo clique define o raio; Enter usa o raio sugerido.</p>';}else if(mode==='zone'){h+=`<div class="field"><label>Categoria</label><select data-param="zoneType">${opts(zoneTypes,a.zoneType)}</select></div>`;}else if(mode==='lot'||mode==='block'||mode==='front'){h+=field('lotFront','Frente padrão (m)',a.lotFront,2,200,.5)+field('lotDepth','Profundidade padrão (m)',a.lotDepth,2,300,.5)+`<div class="field"><label>Fileiras</label><select data-param="lotRows"><option value="1" ${a.lotRows===1?'selected':''}>Uma fileira</option><option value="2" ${a.lotRows===2?'selected':''}>Duas fileiras opostas</option></select></div>`;}else h='<p class="hint">O desenho utiliza metros. Use o encaixe para alinhar os vértices.</p>';if(!['lot','block','front'].includes(mode))h+=`<details><summary>Dimensões dos lotes</summary>${field('lotFront','Frente (m)',a.lotFront,2,200,.5)}${field('lotDepth','Profundidade (m)',a.lotDepth,2,300,.5)}<div class="field"><label>Fileiras</label><select data-param="lotRows"><option value="1" ${a.lotRows===1?'selected':''}>Uma</option><option value="2" ${a.lotRows===2?'selected':''}>Duas opostas</option></select></div></details>`;$('params').innerHTML=h;$('snap').checked=a.snap;$('gridSnap').checked=a.gridSnap;}
function renderLayers(){$('layers').innerHTML=layerDefs.map(([k,l,c])=>{let count=k==='boundary'?+!!p.boundary:k==='road'?p.roads.length+p.rounds.length:k==='block'?p.blocks.length:k==='lot'?p.lots.length:k==='zone'?p.zones.length:+!!p.image;return `<label class="layer"><input type="checkbox" data-layer="${k}" ${visibility[k]?'checked':''}><span class="dot" style="background:${c}"></span>${l}<span class="count">${count}</span></label>`;}).join('');}
