function scheduleMetrics(){clearTimeout(metricsTimer);metricsTimer=setTimeout(calculate,90);}function renderMetrics(){let m=metrics;if(!m)return;let has=!!p.boundary;const aa=x=>has?fmt(x)+' m²':'—';$('mArea').textContent=aa(m.area);$('mHa').textContent=has?fmt(m.area/10000,2)+' ha • perímetro cadastrado':'Defina o perímetro';$('mLotsArea').textContent=aa(m.lot);$('mYield').textContent=has&&m.area?fmt(m.lot/m.area*100,1)+'%':'—';$('mLots').textContent=p.lots.length;$('mBlocks').textContent=p.blocks.length;$('mRoadLen').textContent=fmt(m.len)+' m';$('mRoadArea').textContent=aa(m.road);let arr=[['Sistema viário','#89969a',m.road],...Object.entries(m.zones).map(([k,v])=>[(zoneTypes[k]||zoneTypes.other)[0],(zoneTypes[k]||zoneTypes.other)[1],v]),['Lotes','#d5b674',m.lot],['Área ainda não parcelada','#c8d5bc',m.free]].filter(x=>x[2]>0);$('mix').innerHTML=has&&m.area?'<div class="bar">'+arr.map(([l,c,v])=>`<span style="width:${v/m.area*100}%;background:${c}" title="${l}"></span>`).join('')+'</div>'+arr.map(([l,c,v])=>`<div class="legendrow"><span class="dot" style="background:${c}"></span>${l}<b>${fmt(v/m.area*100,1)}%</b></div>`).join('')+`<p class="tiny">Malha de cálculo: ${fmt(m.step,2)} m. Vias incluem ilha da rotatória.</p>`:'';}
// Flood-fill over a metric grid, then trace the cell boundary. Auto blocks are preliminary polygons.
function simplifyGridCorners(a){let b=a.filter((v,i)=>{let prev=a[(i+a.length-1)%a.length],next=a[(i+1)%a.length];return Math.abs(cross(sub(v,prev),sub(next,v)))>1e-7;});if(b.length<3)return a;return b;}
function extractBlocksRasterLegacy(){let B=p.boundary;if(!B){toast('Desenhe ou importe a gleba primeiro.');return;}if(p.blocks.some(o=>o.auto)&&!confirm('Reextrair quadras automáticas e substituir seus lotes vinculados?'))return;let before=snapshot(),oldIds=new Set(p.blocks.filter(o=>o.auto).map(o=>o.id));p.blocks=p.blocks.filter(o=>!o.auto);p.lots=p.lots.filter(o=>!oldIds.has(o.blockId));let {b,step,nx,ny}=gridFor(B,100000),prep=prepared(),cells=new Uint8Array(nx*ny);let manual=p.blocks.map(o=>({...o,b:bbox(o.pts)}));for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){let v=[b[0]+(x+.5)*step,b[1]+(y+.5)*step];if(insideObj(v,B)&&!onRoad(v,prep)&&!inCategory(v,prep.zone)&&!inCategory(v,manual))cells[y*nx+x]=1;}let created=0;for(let i=0;i<cells.length;i++){if(cells[i]!==1)continue;let q=[i],edges=new Map();cells[i]=2;for(let k=0;k<q.length;k++){let j=q[k],x=j%nx,y=Math.floor(j/nx);for(let [xx,yy] of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){if(xx<0||yy<0||xx>=nx||yy>=ny)continue;let l=yy*nx+xx;if(cells[l]===1){cells[l]=2;q.push(l);}}}if(q.length*step*step<100){for(let j of q)cells[j]=3;continue;}const has=(x,y)=>x>=0&&y>=0&&x<nx&&y<ny&&cells[y*nx+x]===2;const edge=(a,c)=>{let key=a.join(',');if(!edges.has(key))edges.set(key,[]);edges.get(key).push(c);};for(let j of q){let x=j%nx,y=Math.floor(j/nx);if(!has(x,y-1))edge([x,y],[x+1,y]);if(!has(x+1,y))edge([x+1,y],[x+1,y+1]);if(!has(x,y+1))edge([x+1,y+1],[x,y+1]);if(!has(x-1,y))edge([x,y+1],[x,y]);}let rings=[];while(edges.size){let key=edges.keys().next().value,start=key.split(',').map(Number),cur=start,ring=[],guard=0;do{ring.push(cur);let k=cur.join(','),a=edges.get(k);if(!a||!a.length)break;cur=a.pop();if(!a.length)edges.delete(k);if(++guard>nx*ny*4)break;}while(cur.join(',')!==key);if(cur.join(',')===key&&ring.length>=4){let rr=simplifyGridRing(ring.map(v=>[b[0]+v[0]*step,b[1]+v[1]*step]),step*.9);if(rr.length>=3)rings.push(rr);}}for(let j of q)cells[j]=3;if(!rings.length)continue;rings.sort((a,c)=>Math.abs(area(c))-Math.abs(area(a)));let o={id:uid(),name:'Q'+String(p.blocks.length+1).padStart(2,'0'),pts:rings[0],holes:rings.slice(1),auto:true};p.blocks.push(o);created++;}p.derivedDirty=false;selection=null;commit(before);toast(created+' quadra(s) extraída(s). Malha: '+fmt(step,2)+' m.');}
function pointInOrEdge(v,o){if(insideObj(v,o))return true;let rings=[o.pts,...(o.holes||[])];return rings.some(a=>a.some((q,i)=>dist(v,nearest(v,q,a[(i+1)%a.length]))<1e-5));}
function validLot(rect,block,prep){let samples=[...rect,centroid(rect)];for(let i=0;i<4;i++){let a=rect[i],b=rect[(i+1)%4];for(let t=.1;t<1;t+=.1)samples.push(lerp(a,b,t));}if(!samples.every(v=>pointInOrEdge(v,block)&&(!p.boundary||pointInOrEdge(v,p.boundary))&&!onRoad(v,prep)&&!inCategory(v,prep.zone)))return false;for(let ring of [block.pts,...(block.holes||[])]){for(let i=0;i<ring.length;i++)for(let k=0;k<4;k++)if(segCross(ring[i],ring[(i+1)%ring.length],rect[k],rect[(k+1)%4]))return false;if(ring.some(v=>inside(v,rect)&&!rect.some((a,i)=>dist(v,nearest(v,a,rect[(i+1)%4]))<1e-5)))return false;}for(let o of prep.lot){if(!o.b)continue;let rb=bbox(rect);if(rb[2]<=o.b[0]||rb[0]>=o.b[2]||rb[3]<=o.b[1]||rb[1]>=o.b[3])continue;let c=centroid(rect),co=centroid(o.pts);if(insideObj(c,o)||inside(co,rect)||rect.some(v=>insideObj(lerp(v,c,.001),o))||o.pts.some(v=>inside(lerp(v,co,.001),rect)))return false;for(let i=0;i<o.pts.length;i++)for(let j=0;j<4;j++)if(segCross(o.pts[i],o.pts[(i+1)%o.pts.length],rect[j],rect[(j+1)%4]))return false;}return true;}
function roadEdgeDistance(v,prep){let d=Infinity;for(let o of prep.round)d=Math.min(d,Math.abs(dist(v,o.c)-o.r));for(let r of prep.road)for(let i=0;i<r.pts.length-1;i++)d=Math.min(d,Math.abs(dist(v,nearest(v,r.pts[i],r.pts[i+1]))-r.w));return d;}
function generateLots(){let sel=selected();if(!sel||sel[0]!=='block'){toast('Selecione uma quadra para parcelar.');return;}let o=sel[1];if(p.lots.some(l=>l.blockId===o.id&&l.auto)&&!confirm('Substituir os lotes automáticos desta quadra?'))return;let before=snapshot();p.lots=p.lots.filter(l=>!(l.blockId===o.id&&l.auto));let a=o.pts,prep=prepared(),step=o.auto&&p.boundary?gridFor(p.boundary,100000).step:0,clearance=Math.max(.12,step*1.1),tol=Math.max(2.5,step*3);let roadFacing=a.map((q,i)=>({i,len:dist(q,a[(i+1)%a.length]),score:[.2,.5,.8].filter(t=>roadEdgeDistance(lerp(q,a[(i+1)%a.length],t),prep)<=tol).length})).filter(q=>q.score>=2).sort((x,y)=>y.len-x.len);let fi=o.front??roadFacing[0]?.i;if(fi==null){commit(before);toast('Não há divisa próxima a uma via. Defina o acesso viário.');return;}let start=a[fi],u=norm(sub(a[(fi+1)%a.length],start)),v=perp(u);if(dot(sub(centroid(a),start),v)<0)v=mul(v,-1);let uv=a.map(q=>[dot(sub(q,start),u),dot(sub(q,start),v)]),b=bbox(uv),f=p.params.lotFront,d=p.params.lotDepth,rows=[{y:clearance,back:false}];if(p.params.lotRows===2&&b[3]>=2*d+2*clearance)rows.push({y:b[3]-d-clearance,back:true});let count=0;const toWorld=(x,y)=>add(start,add(mul(u,x),mul(v,y)));for(let row of rows){let yy=row.y;if(yy+d>b[3]+.01)continue;let num=Math.floor((b[2]-b[0])/f),margin=(b[2]-b[0]-num*f)/2;for(let j=0;j<num&&count<3000;j++){let x=b[0]+margin+j*f,rect=[toWorld(x,yy),toWorld(x+f,yy),toWorld(x+f,yy+d),toWorld(x,yy+d)];let face=row.back?[rect[2],rect[3]]:[rect[0],rect[1]];if(![.2,.5,.8].every(t=>roadEdgeDistance(lerp(face[0],face[1],t),prep)<=tol))continue;if(!validLot(rect,o,prep))continue;let l={id:uid(),name:'Lote '+String(count+1).padStart(2,'0'),pts:rect,blockId:o.id,auto:true};p.lots.push(l);count++;}}commit(before);toast(count?count+' lote(s) gerado(s). Confira frentes e acessos.':'Nenhum lote coube com acesso próximo à via. Ajuste dimensões ou frente.');}
function download(name,data,mime){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}function filename(){return p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'_').slice(0,75)||'tracado';}function saveJSON(){download(filename()+'.json',JSON.stringify(p,null,2),'application/json');toast('Projeto exportado.');}
function exportGeo(){if(!p.anchor.confirmed){toast('Defina a origem WGS84 antes de exportar GeoJSON.');return;}let feats=allObjects().map(([t,o])=>{let prop={tipo:t,nome:o.name,id:o.id};if(t==='road'){Object.assign(prop,{largura_m:o.width,hierarquia:o.cls,curva:o.smooth});return {type:'Feature',properties:prop,geometry:{type:'LineString',coordinates:roadPts(o).map(toGeo)}};}if(t==='round'){Object.assign(prop,{raio_externo_m:o.r,largura_anel_m:o.w});return {type:'Feature',properties:prop,geometry:{type:'Point',coordinates:toGeo(o.c)}};}if(t==='zone')prop.categoria=o.kind;if(t==='block'){const s=blockStats(o);Object.assign(prop,{area_m2:s.area,perimetro_m:s.outer,comprimento_m:s.width,largura_m:s.depth,automatico:!!o.auto});}if(t==='lot'){prop.quadra=o.blockId;prop.revisar=!!o.blockConflict;}let rings=[o.pts,...(o.holes||[])].map((a,i)=>{let q=a.map(toGeo);if((i===0&&area(q)<0)||(i>0&&area(q)>0))q.reverse();q.push(q[0]);return q;});return {type:'Feature',properties:prop,geometry:{type:'Polygon',coordinates:rings}};});download(filename()+'.geojson',JSON.stringify({type:'FeatureCollection',features:feats},null,2),'application/geo+json');toast('GeoJSON exportado.');}
function exportDXF(){let lines=['0','SECTION','2','HEADER','9','$ACADVER','1','AC1015','9','$INSUNITS','70','6','0','ENDSEC','0','SECTION','2','ENTITIES'];let push=(...a)=>lines.push(...a.map(String));function poly(a,layer,closed){push(0,'LWPOLYLINE',100,'AcDbEntity',8,layer,100,'AcDbPolyline',90,a.length,70,closed?1:0);for(let v of a)push(10,v[0].toFixed(4),20,(-v[1]).toFixed(4));}for(let [t,o] of allObjects()){let l={boundary:'GLEBA',road:'EIXOS_VIARIOS',round:'ROTATORIAS',block:'QUADRAS',lot:'LOTES',zone:'AREAS_'+String(o.kind||'OUTRAS').toUpperCase()}[t];if(t==='road'){poly(roadPts(o),l,false);poly(offset(roadPts(o),o.width/2),'DIVISAS_VIARIAS',false);poly(offset(roadPts(o),-o.width/2),'DIVISAS_VIARIAS',false);}else if(t==='round'){for(let r of [o.r,o.r-o.w])if(r>0)push(0,'CIRCLE',100,'AcDbEntity',8,l,100,'AcDbCircle',10,o.c[0].toFixed(4),20,(-o.c[1]).toFixed(4),30,0,40,r.toFixed(4));}else{poly(o.pts,l,true);for(let a of o.holes||[])poly(a,l,true);}}push(0,'ENDSEC',0,'EOF');download(filename()+'.dxf',lines.join('\r\n')+'\r\n','application/dxf');toast('DXF exportado em metros locais.');}
function validateProject(o){if(!o||o.version!==1||!o.anchor||!Number.isFinite(+o.anchor.lat)||Math.abs(o.anchor.lat)>85||!Number.isFinite(+o.anchor.lon)||Math.abs(o.anchor.lon)>180)throw Error('Projeto JSON inválido.');let goodPts=a=>Array.isArray(a)&&a.length>=2&&a.every(v=>Array.isArray(v)&&v.length>=2&&v.slice(0,2).every(x=>typeof x==='number'&&Number.isFinite(x)));for(let k of ['roads','rounds','blocks','lots','zones'])if(!Array.isArray(o[k]))throw Error('Estrutura de projeto incompleta.');let ids=new Set();for(let q of [...(o.boundary?[o.boundary]:[]),...o.roads,...o.rounds,...o.blocks,...o.lots,...o.zones]){if(!q.id||! /^[a-zA-Z0-9_-]+$/.test(q.id)||ids.has(q.id))q.id=uid();ids.add(q.id);if(q.c){if(!goodPts([q.c,q.c])||!(q.r>=2&&q.r<=150&&q.w>0&&q.w<q.r))throw Error('Rotatória inválida.');}else if(!goodPts(q.pts))throw Error('Vértices inválidos.');if(q.holes&&!q.holes.every(goodPts))throw Error('Anel inválido.');}for(let r of o.roads)if(!(r.width>0&&r.width<=100))throw Error('Largura de via inválida.');for(let q of [o.boundary,...o.blocks,...o.lots,...o.zones].filter(Boolean))if(q.pts.length<3||Math.abs(area(q.pts))<.01)throw Error('Polígono inválido.');if(o.image&&(!/^data:image\/(png|jpeg|webp|gif);base64,/.test(o.image.data)||!(o.image.w>0&&o.image.h>0)))o.image=null;for(let z of o.zones)if(!zoneTypes[z.kind])z.kind='other';o.name=String(o.name||'Estudo importado');o.params={...defaults,...o.params};for(let k of ['width','gap','copies','roundWidth','roundRadius','lotFront','lotDepth','lotRows'])if(!Number.isFinite(+o.params[k]))o.params[k]=defaults[k];return o;}
function openState(q){let before=snapshot();closeParcel();p=q;normalizePrecision(p);normalizeParcel(p);selection=null;draft=[];refRoad=null;mode='select';commit(before);fit();}
function importGeo(obj,name){let feats=obj.type==='FeatureCollection'?obj.features:obj.type==='Feature'?[obj]:[{type:'Feature',geometry:obj,properties:{}}];if(!Array.isArray(feats))throw Error('GeoJSON inválido.');let f=feats.find(x=>x.geometry?.type==='Polygon'&&x.properties?.tipo==='boundary')||feats.find(x=>['Polygon','MultiPolygon'].includes(x.geometry?.type));if(!f)throw Error('O arquivo precisa conter um polígono de gleba.');let poly=f.geometry.type==='MultiPolygon'?f.geometry.coordinates[0]:f.geometry.coordinates,ring=poly[0];if(!ring||ring.length<4)throw Error('Perímetro inválido.');let ll=ring[0];if(!ll||!ll.every(Number.isFinite)||Math.abs(ll[0])>180||Math.abs(ll[1])>85)throw Error('Use coordenadas geográficas WGS84.');let old=p,pnew=blank();pnew.name=name;pnew.anchor={lon:ll[0],lat:ll[1],confirmed:true};p=pnew;const clean=a=>{let q=a.map(v=>{if(!Array.isArray(v)||v.length<2||!v.slice(0,2).every(Number.isFinite)||Math.abs(v[0])>180||Math.abs(v[1])>85)throw Error('Coordenadas WGS84 inválidas.');return fromGeo(v);});if(q.length>2&&dist(q[0],q.at(-1))<.01)q.pop();return q;};try{pnew.boundary={id:uid(),name:'Gleba importada',pts:clean(ring),holes:poly.slice(1).map(clean)};if(!simple(pnew.boundary.pts))throw Error('Perímetro possui cruzamento ou área inválida.');let ids=new Map(),lotLinks=[];for(let a of feats){if(a===f||!a.geometry)continue;let g=a.geometry,k=a.properties||{},t=k.tipo,nm=String(k.nome||'Elemento importado');if(g.type==='LineString'&&(t==='road'||!t)){pnew.roads.push({id:uid(),name:nm,pts:clean(g.coordinates),width:clamp(n(k.largura_m,14),1,100),cls:k.hierarquia||'Local',smooth:false});}else if(g.type==='Point'&&t==='round'){let r=clamp(n(k.raio_externo_m,18),3,150);pnew.rounds.push({id:uid(),name:nm,c:fromGeo(g.coordinates),r,w:clamp(n(k.largura_anel_m,8),1,r-.5)});}else if(g.type==='Polygon'&&['zone','block','lot'].includes(t)){let o={id:uid(),name:nm,pts:clean(g.coordinates[0]),holes:g.coordinates.slice(1).map(clean)};if(t==='zone')o.kind=zoneTypes[k.categoria]?k.categoria:'other';if(t==='block'&&k.id)ids.set(k.id,o.id);if(t==='lot'&&k.quadra)lotLinks.push([o,k.quadra]);pnew[{zone:'zones',block:'blocks',lot:'lots'}[t]].push(o);}}for(let [o,k] of lotLinks)if(ids.has(k))o.blockId=ids.get(k);}finally{p=old;}openState(pnew);setBase('satellite');toast(f.geometry.type==='MultiPolygon'?'Primeiro polígono da gleba importado.':'Geometria importada em WGS84.');}
function importKML(s,name){let doc=new DOMParser().parseFromString(s,'text/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('KML inválido.');let polygons=[...doc.getElementsByTagNameNS('*','Polygon')];if(!polygons.length)throw Error('Não foi encontrado um polígono no KML.');let poly=polygons[0],getRing=e=>e.getElementsByTagNameNS('*','coordinates')[0]?.textContent.trim().split(/\s+/).map(a=>a.split(',').slice(0,2).map(Number));let outer=poly.getElementsByTagNameNS('*','outerBoundaryIs')[0],holes=[...poly.getElementsByTagNameNS('*','innerBoundaryIs')].map(getRing);importGeo({type:'Polygon',coordinates:[getRing(outer),...holes]},name);if(polygons.length>1)toast('Primeiro polígono do KML importado.');}
function askNew(d){if(!confirm(d?'Abrir exemplo e substituir o estudo atual? Exporte o JSON antes, se necessário.':'Criar projeto vazio? Exporte o JSON do estudo atual antes, se necessário.'))return;openState(d?demo():blank());}
$('fileInput').addEventListener('change',async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;try{let s=await f.text(),name=f.name.replace(/\.[^.]+$/,'');if(f.name.toLowerCase().endsWith('.kml'))importKML(s,name);else{let q=JSON.parse(s);if(q.version===1&&q.roads)openState(validateProject(q));else importGeo(q,name);}}catch(err){toast('Falha na importação: '+err.message);}});
$('imgInput').addEventListener('change',e=>{let f=e.target.files[0];e.target.value='';if(!f)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type)){toast('Use PNG, JPG, WebP ou GIF.');return;}let r=new FileReader();r.onload=()=>{let im=new Image();im.onload=()=>{let canvas=document.createElement('canvas'),scale=Math.min(1,2200/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);pendingImage={data:canvas.toDataURL('image/jpeg',.85),ratio:im.height/im.width};$('imgX').value=Math.round(view.cx-W/2/view.z);$('imgY').value=Math.round(view.cy-H/2/view.z);$('imgWidth').value=Math.round(W/view.z);$('imageDialog').showModal();};im.src=r.result;};r.readAsDataURL(f);});
$('anchorApply').onclick=()=>{let lat=+$('lat').value,lon=+$('lon').value;if(!$('lat').value||!$('lon').value||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>85||Math.abs(lon)>180){toast('Coordenadas inválidas.');return;}let before=snapshot();p.anchor={lat,lon,confirmed:true};tileKey='';commit(before);$('anchorDialog').close();};$('imgApply').onclick=()=>{if(!pendingImage)return;let w=+$('imgWidth').value,x=+$('imgX').value,y=+$('imgY').value;if(!(w>0)||!Number.isFinite(x)||!Number.isFinite(y)){toast('Dimensões inválidas.');return;}let before=snapshot();p.image={data:pendingImage.data,x,y,w,h:w*pendingImage.ratio};pendingImage=null;commit(before);$('imageDialog').close();toast('Imagem de base importada.');};
