$('fileToggle').onclick=()=>$('fileMenu').classList.toggle('open');$('fileMenu').onclick=e=>{let a=e.target.closest('[data-action]')?.dataset.action;if(a)fileAction(a);};document.addEventListener('click',e=>{if(!e.target.closest('#fileMenu,#fileToggle'))$('fileMenu').classList.remove('open');});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('newProject').onclick=()=>askNew(false);$('emptyDemo').onclick=()=>openState(demo());$('emptyDraw').onclick=()=>setMode('boundary');$('emptyImport').onclick=()=>$('fileInput').click();$('saveBtn').onclick=()=>{try{localStorage.setItem('evora-tracado-v1',snapshot());$('saveStatus').textContent='Salvo neste navegador • metros';toast('Estudo salvo neste navegador. Exporte JSON para compartilhar.');}catch(e){saveJSON();}};$('projectName').onchange=e=>{let before=snapshot();p.name=e.target.value.trim()||'Estudo sem título';commit(before);};$('tools').onclick=e=>{let m=e.target.closest('[data-tool]')?.dataset.tool;if(m)setMode(m);};$('params').onchange=e=>{let k=e.target.dataset.param;if(!k)return;let val=e.target.type==='number'?clamp(n(e.target.value,defaults[k]),+e.target.min,+e.target.max):k==='lotRows'?+e.target.value:e.target.value;if(k==='copies')val=Math.round(val);let before=snapshot();p.params[k]=val;commit(before);};$('snap').onchange=e=>{p.params.snap=e.target.checked;autoSave();};$('gridSnap').onchange=e=>{p.params.gridSnap=e.target.checked;autoSave();};$('layers').onchange=e=>{let k=e.target.dataset.layer;if(k){visibility[k]=e.target.checked;renderDrawing();}};
