/* Studio additions: explicit metric commands, crossing snaps, gesture control and local archive. */
let crossingCache=[];
function segmentIntersection(a,b,c,d){
  const u=sub(b,a),v=sub(d,c),det=cross(u,v);
  if(Math.abs(det)<1e-9)return null;
  const delta=sub(c,a),t=cross(delta,v)/det,s=cross(delta,u)/det;
  return t>=-1e-8&&t<=1+1e-8&&s>=-1e-8&&s<=1+1e-8?add(a,mul(u,t)):null;
}
function rebuildCrossings(){
  const segs=[];
  for(const r of p.roads){const pts=roadPts(r);for(let i=1;i<pts.length;i++)segs.push({a:pts[i-1],b:pts[i],id:r.id,w:r.width,box:bbox([pts[i-1],pts[i]])})}
  const found=[];
  if(segs.length<=1800)for(let i=0;i<segs.length;i++)for(let j=i+1;j<segs.length;j++){
    const a=segs[i],b=segs[j];
    if(a.id===b.id||a.box[2]<b.box[0]||a.box[0]>b.box[2]||a.box[3]<b.box[1]||a.box[1]>b.box[3])continue;
    const v=segmentIntersection(a.a,a.b,b.a,b.b);
    if(v&&!found.some(x=>dist(x.v,v)<.1))found.push({v,ids:[a.id,b.id],radius:Math.max(a.w,b.w)/2+1});
  }
  crossingCache=found;
}
function snapPointStudio2(v,ignore=null){
  let best=snapPointBase(v,ignore);
  if(!p.params.snap||!visibility.road)return best;
  let distance=11/view.z;
  for(const x of crossingCache){if(x.ids.includes(ignore))continue;const d=dist(v,x.v);if(d<distance&&(!snapInfo||d<=dist(v,best)+3/view.z)){best=x.v;distance=d;snapInfo='cruzamento'}}
  return best;
}
function draftPointLegacy(raw,orth=false,ignore=null){
  if(orth&&['road','curve','boundary','block','lot','zone'].includes(mode)){
    const a=draft.at(-1)||(drag?.kind==='click'&&drag.moved?drag.start:null);
    if(a){snapInfo='ortogonal';return Math.abs(raw[0]-a[0])>=Math.abs(raw[1]-a[1])?[raw[0],a[1]]:[a[0],raw[1]]}
  }
  return snapPoint(raw,ignore);
}
function roadMarkMask(){
  const rings=p.rounds.map(o=>'<circle cx="'+o.c[0]+'" cy="'+o.c[1]+'" r="'+(o.r+1)+'" fill="black"/>').join('');
  const junctions=crossingCache.map(o=>'<circle cx="'+o.v[0]+'" cy="'+o.v[1]+'" r="'+o.radius+'" fill="black"/>').join('');
  const x=view.cx-W/(2*view.z)-40/view.z,y=view.cy-H/(2*view.z)-40/view.z,w=(W+80)/view.z,h=(H+80)/view.z;
  const bounds=' x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'"';
  return '<defs><mask id="roadMarksMask" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse"'+bounds+'><rect'+bounds+' fill="white"/>'+rings+junctions+'</mask></defs>';
}
function simplifyGridRing(a,epsilon){
  a=simplifyGridCorners(a);if(a.length<5)return a;
  let k=1;for(let i=2;i<a.length;i++)if(dist(a[i],a[0])>dist(a[k],a[0]))k=i;
  function simplifyLine(line){
    if(line.length<3)return line;
    let keep=new Uint8Array(line.length);keep[0]=keep[line.length-1]=1;const stack=[[0,line.length-1]];
    while(stack.length){const [lo,hi]=stack.pop();let max=epsilon,idx=-1;for(let i=lo+1;i<hi;i++){const d=dist(line[i],nearest(line[i],line[lo],line[hi]));if(d>max){max=d;idx=i}}
      if(idx>=0){keep[idx]=1;stack.push([lo,idx],[idx,hi])}
    }return line.filter((_,i)=>keep[i]);
  }
  const q=[...simplifyLine(a.slice(0,k+1)).slice(0,-1),...simplifyLine([...a.slice(k),a[0]]).slice(0,-1)];
  return q.length>=3&&q.length<500&&simple(q)&&Math.abs(area(q)-area(a))<=Math.max(5,Math.abs(area(a))*.015)?q:a;
}
const cadModes=['road','curve','boundary','block','lot','zone','parcelArea','guide','measure'];
function syncCad(){
  const active=cadModes.includes(mode);$('cadCommand').classList.toggle('hidden',!active);
  $('cadAdd').disabled=!draft.length;$('backPoint').disabled=!draft.length;
  $('cadHint').textContent=draft.length?draft.length+' ponto(s) · 0° leste / 90° norte':'Primeiro ponto na prancheta';
  $('quickSelect').classList.toggle('on',mode==='select');$('quickPan').classList.toggle('on',mode==='pan');
}
function exactPoint(){
  if(!draft.length||!cadModes.includes(mode))return toast('Marque o primeiro ponto na prancheta.');
  const len=Number($('cadLength').value),deg=Number($('cadAngle').value);
  if(!Number.isFinite(len)||len<=0||len>100000||!Number.isFinite(deg)||!$('cadAngle').value)return toast('Informe comprimento positivo e ângulo válido.');
  const a=deg*Math.PI/180,next=add(draft.at(-1),[len*Math.cos(a),-len*Math.sin(a)]);if(mode==='guide'||mode==='measure'){precisionClick(next,next,null);cursor=next;}else{beginShape(next);cursor=draft.at(-1);}renderOverlay();svg.focus();
}
function setBase(which){const b=document.querySelector('[data-base="'+which+'"]');if(b&&base!==which)b.click();}
const libraryKey='evora-tracado-library-v2';
function libraryRead(){try{const a=JSON.parse(localStorage.getItem(libraryKey)||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function libraryRender(){
  const list=$('projectList');list.replaceChildren();
  const items=libraryRead().sort((a,b)=>b.updated-a.updated);
  if(!items.length){list.textContent='Nenhuma versão arquivada. Salve o estudo atual.';return}
  for(const x of items){const row=document.createElement('div');row.className='project-row';const info=document.createElement('div');const name=document.createElement('b');name.textContent=x.name||'Sem título';const date=document.createElement('small');date.textContent=new Date(x.updated).toLocaleString('pt-BR');info.append(name,date);
    const open=document.createElement('button');open.className='small';open.textContent='Abrir';open.onclick=()=>{if(!confirm('Abrir esta versão? Exporte ou arquive alterações do estudo atual.'))return;try{openState(validateProject(JSON.parse(x.data)));$('libraryDialog').close();if(p.anchor.confirmed)setBase('satellite')}catch(e){toast('Versão inválida: '+e.message)}};
    const del=document.createElement('button');del.className='small danger';del.textContent='Excluir';del.onclick=()=>{if(!confirm('Excluir esta versão da biblioteca local?'))return;try{localStorage.setItem(libraryKey,JSON.stringify(libraryRead().filter(y=>y.id!==x.id)));libraryRender()}catch{toast('Não foi possível excluir a versão.')}};
    row.append(info,open,del);list.append(row)
  }
}
function archiveCurrent(){
  try{const a=libraryRead();a.push({id:uid(),name:p.name,updated:Date.now(),data:snapshot()});localStorage.setItem(libraryKey,JSON.stringify(a));libraryRender();toast('Versão arquivada neste navegador.')}catch{toast('Limite de armazenamento. Exporte o projeto em JSON.')}
}
function installStudio(){
  $('quickSelect').onclick=()=>setMode('select');$('quickPan').onclick=()=>setMode('pan');
  $('backPoint').onclick=()=>{draft.pop();renderOverlay();svg.focus()};
  $('cadAdd').onclick=exactPoint;$('cadLength').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();exactPoint()}});$('cadAngle').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();exactPoint()}});
  $('libraryBtn').onclick=()=>{libraryRender();$('libraryDialog').showModal()};$('archiveCurrent').onclick=archiveCurrent;$('newFromLibrary').onclick=()=>{$('libraryDialog').close();askNew(false)};
  $('geoQuick').onclick=()=>fileAction('anchor');
  $('parseCoords').onclick=()=>{const matches=$('coordPaste').value.trim().match(/[-+]?\d+(?:[.]\d+)?/g);if(!matches||matches.length!==2)return toast('Cole latitude e longitude separadas por vírgula.');const [lat,lon]=matches.map(Number);if(Math.abs(lat)>85||Math.abs(lon)>180)return toast('Coordenadas fora do intervalo.');$('lat').value=lat;$('lon').value=lon};
  $('anchorApply').addEventListener('click',()=>{if(p.anchor.confirmed&&!$('anchorDialog').open){setBase('satellite');fit()}});
  $('tileLayer').addEventListener('error',()=>{if(base!=='grid')$('mapWarning').classList.remove('hidden')},true);
  $('tileLayer').addEventListener('load',()=>{$('mapWarning').classList.add('hidden')},true);
  // Two-finger zoom/pan. Capture phase prevents a pinch from creating or moving geometry.
  const contacts=new Map();let pinch=null,suppress=false;
  const mid=()=>{const [a,b]=[...contacts.values()];return [(a[0]+b[0])/2,(a[1]+b[1])/2]};
  const span=()=>{const [a,b]=[...contacts.values()];return Math.max(8,dist(a,b))};
  const localMid=()=>{const b=svg.getBoundingClientRect(),m=mid();return [m[0]-b.left,m[1]-b.top]};
  svg.addEventListener('pointerdown',e=>{
    if(e.pointerType!=='touch')return;contacts.set(e.pointerId,[e.clientX,e.clientY]);
    if(contacts.size>=2||suppress){e.stopImmediatePropagation();e.preventDefault();try{svg.setPointerCapture(e.pointerId)}catch{};if(drag?.kind==='object'&&drag.moved)replaceState(drag.before);drag=null;suppress=true;if(contacts.size===2){const m=localMid();pinch={z:view.z,span:span(),world:[view.cx+(m[0]-W/2)/view.z,view.cy+(m[1]-H/2)/view.z]}}}
  },true);
  svg.addEventListener('pointermove',e=>{
    if(e.pointerType!=='touch'||!contacts.has(e.pointerId))return;contacts.set(e.pointerId,[e.clientX,e.clientY]);if(!suppress)return;e.stopImmediatePropagation();e.preventDefault();
    if(pinch&&contacts.size>=2){const m=localMid();view.z=clamp(pinch.z*span()/pinch.span,.025,70);view.cx=pinch.world[0]-(m[0]-W/2)/view.z;view.cy=pinch.world[1]-(m[1]-H/2)/view.z;renderView()}
  },true);
  const endTouch=e=>{if(e.pointerType!=='touch')return;contacts.delete(e.pointerId);if(suppress){e.stopImmediatePropagation();e.preventDefault();pinch=null;drag=null;if(!contacts.size)suppress=false}};
  svg.addEventListener('pointerup',endTouch,true);svg.addEventListener('pointercancel',endTouch,true);
  window.addEventListener('pagehide',()=>{try{localStorage.setItem('evora-tracado-v1',snapshot())}catch{}});
}

